function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, side: THREE.DoubleSide });
}

function makeLineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: true, opacity });
}

function makeNoiseTexture() {
  const cnv = document.createElement('canvas');
  cnv.width = 96;
  cnv.height = 160;
  const ctx = cnv.getContext('2d');
  const img = ctx.createImageData(cnv.width, cnv.height);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 120 + Math.random() * 95;
    img.data[i] = v + Math.random() * 35;
    img.data[i + 1] = v + Math.random() * 15;
    img.data[i + 2] = v + Math.random() * 45;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  for (let k = 0; k < 14; k++) {
    ctx.fillStyle = `rgba(${80 + Math.random() * 80},${80 + Math.random() * 80},${80 + Math.random() * 80},0.22)`;
    ctx.beginPath();
    ctx.ellipse(Math.random() * 96, Math.random() * 160, 8 + Math.random() * 20, 4 + Math.random() * 18, Math.random() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(cnv);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function addEdges(mesh, color = black) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color })
  );
  edges.position.copy(mesh.position);
  edges.rotation.copy(mesh.rotation);
  edges.scale.copy(mesh.scale);
  scene.add(edges);
  architectureObjects.push(edges);
  return edges;
}

function createVolume({ id, x, h, w, depth, color = 0xc97955, dark = 0x7f3a20, z = -0.02, noisy = false, attention = false }) {
  const geom = new THREE.BoxGeometry(w, h, depth);
  const mats = noisy
    ? [
        makeMat(0x222222), makeMat(0xdddddd), makeMat(0xbbbbbb), makeMat(0x777777),
        new THREE.MeshBasicMaterial({ map: makeNoiseTexture(), side: THREE.DoubleSide }),
        makeMat(0x999999)
      ]
    : [
        makeMat(0xa95432), makeMat(0x9a4a2c), makeMat(0xd7906c), makeMat(0x663018),
        makeMat(color), makeMat(dark)
      ];
  const mesh = new THREE.Mesh(geom, mats);
  mesh.position.set(x, h / 2, z - depth / 2);
  mesh.userData.id = id;
  scene.add(mesh);
  addEdges(mesh);
  architectureObjects.push(mesh);
  volumeMeshes.push(mesh);
  if (attention) {
    registerInteractive(mesh, {
      title: 'Self-attention block',
      tooltip: 'Click to inspect 16×16 self-attention',
      body: 'At 16×16 resolution there are 256 spatial tokens. Self-attention computes A = softmax(QKᵀ / √d), so one selected position can mix information from every other position.',
      onClick: () => setAttentionOverlay(true)
    });
  }
  return mesh;
}

function addArrowLine(points, color = black, opts = {}) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = makeLineMat(color, opts.opacity ?? 1);
  const line = new THREE.Line(geom, mat);
  scene.add(line);
  architectureObjects.push(line);
  if (opts.pulsable) pulseObjects.push(line);

  if (opts.head !== false && points.length >= 2) {
    const a = points[points.length - 2];
    const b = points[points.length - 1];
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(opts.headRadius ?? 0.07, opts.headLength ?? 0.18, 24),
      makeMat(color, opts.opacity ?? 1)
    );
    cone.position.copy(b).sub(dir.clone().multiplyScalar((opts.headLength ?? 0.18) * 0.45));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    scene.add(cone);
    architectureObjects.push(cone);
    if (opts.pulsable) pulseObjects.push(cone);
  }
  return line;
}

function addPolyline(points, color = copper, opts = {}) {
  return addArrowLine(points, color, { ...opts, head: opts.head ?? true, headRadius: 0.08, headLength: 0.22 });
}

