function addGrid(group, originX, originY, n, size, col, opacity = 0.45) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const k = i * size / n;
    pts.push(new THREE.Vector3(originX + k, originY, 0.34), new THREE.Vector3(originX + k, originY + size, 0.34));
    pts.push(new THREE.Vector3(originX, originY + k, 0.34), new THREE.Vector3(originX + size, originY + k, 0.34));
  }
  const l = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts), makeLineMat(col, opacity));
  group.add(l);
  return l;
}
