function setDimmed(dim) {
  for (const obj of architectureObjects) {
    obj.traverse?.(o => {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) {
        if (!m) continue;
        m.transparent = true;
        m.opacity = dim ? Math.min(m.opacity, 0.23) : 1;
      }
    });
  }
}

function setAttentionOverlay(open) {
  attentionOpen = open;
  overlayGroup.visible = open;
  document.getElementById('btnCloseAttention').style.display = open ? '' : 'none';
  setDimmed(open);
  for (const e of overlayLabels) e.div.style.display = open ? '' : 'none';
  if (open) showPopup('Self-attention inspection', 'The selected query cell connects to all 16×16 = 256 spatial positions using A = softmax(QKᵀ / √d). A plain residual block only mixes a local convolutional neighborhood.');
  else hidePopup();
}

function updateTimestep(t) {
  const val = Number(t);
  document.getElementById('tReadout').textContent = val;
  tLabel.div.innerHTML = `t = ${val}`;
  const s = Math.sin(2 * Math.PI * val / 1000);
  const c = Math.cos(2 * Math.PI * val / 1000);
  const mix = Math.round(110 + 90 * (s * 0.5 + 0.5));
  const col = new THREE.Color(`rgb(${60},${mix},${150 + Math.round(60 * (c * 0.5 + 0.5))})`);
  for (const line of injectionLines) line.material.color.copy(col);
  for (let i = 0; i < injectionLabels.length; i++) {
    injectionLabels[i].div.innerHTML = `${s >= 0 ? '+' : ''}${s.toFixed(2)}, ${c.toFixed(2)}`;
