function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, side: THREE.DoubleSide });
}

function makeLineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: true, opacity });
}

function makeNoiseTexture() {
  const cnv = document.createElement('canvas');
  cnv.width = 96;
  cnv.height = 160;
  const ctx = cnv.getContext('2d');
  const img = ctx.createImageData(cnv.width, cnv.height);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 120 + Math.random() * 95;
    img.data[i] = v + Math.random() * 35;
    img.data[i + 1] = v + Math.random() * 15;
    img.data[i + 2] = v + Math.random() * 45;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  for (let k = 0; k < 14; k++) {
    ctx.fillStyle = `rgba(${80 + Math.random() * 80},${80 + Math.random() * 80},${80 + Math.random() * 80},0.22)`;
    ctx.beginPath();
    ctx.ellipse(Math.random() * 96, Math.random() * 160, 8 + Math.random() * 20, 4 + Math.random() * 18, Math.random() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(cnv);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function addEdges(mesh, color = black) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color })
  );
  edges.position.copy(mesh.position);
  edges.rotation.copy(mesh.rotation);
  edges.scale.copy(mesh.scale);
  scene.add(edges);
  architectureObjects.push(edges);
  return edges;
}

