</div>
<div id="stepTitle" style="font-weight:bold;color:#7b3a24">Middle diffusion timestep</div>
<div id="stepNarration" style="line-height:1.35;color:#333">At an intermediate t, the blue time-embedding arrows carry a different conditioning value to all encoder and decoder blocks.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// rounded-corner legend box → ShapeGeometry white panel with black outline in the upper-left
// legend residual entry → dark horizontal Line arrow labeled "Res. block"
// legend self-attention entry → pale-blue horizontal Line arrow labeled "Res. block + self-attention"
// input image sheet → thin noisy BoxGeometry sheet, 256×256×3 with square 256 front face and tiny C depth
// feature volumes → BoxGeometry cuboids with square H×W front faces and channel depth on z-thickness
// volume outlines → black EdgesGeometry LineSegments attached to each cuboid
// dimension leaders → black Line arrows with cone heads from rotated labels to the matching volumes
// concatenate skips → copper polylines with cone arrowheads at decoder ends and centered "Concatenate" labels
// time node → muted-blue outlined Circle/Ring line labeled "t"
// time embedding trunk → muted-blue horizontal Line along the bottom with label "time embedding"
// time injection arrows → muted-blue diagonal Line arrows from the trunk to every residual/self-attention block
// forward path arrowheads → small black Line arrows along the baseline between consecutive volumes
// active stage halo → yellow transparent EdgesGeometry box around the current stage
// self-attention overlay → hidden Group with dim panel, local residual-grid mini-panel, 16×16 attention grid, query cell, and global attention rays

const copper = 0xcf7b5b;
const copperDark = 0x7f3a20;
const copperLight = 0xc97955;
const copperText = '#7b3a24';
const blue = 0x4b6d7c;
const paleBlue = '#6f9bb5';
const black = 0x000000;

const architectureObjects = [];
const pulseObjects = [];
const volumeMeshes = [];
const injectionLines = [];
const injectionDots = [];
const skipByStage = {};
const transitionByStage = {};
const overlayLabels = [];
const rotatedLabels = [];
const baseOpacity = new WeakMap();

let passRunning = false;
let passStart = 0;
let activeStageIndex = -1;
let attentionOpen = false;
const passStageMs = 850;

function mat(color, opacity = 1, extra = {}) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    ...extra
  });
  baseOpacity.set(m, opacity);
  return m;
}

function lineMat(color, opacity = 1) {
  const m = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  baseOpacity.set(m, opacity);
  return m;
}

function setMaterialOpacity(material, opacity) {
  if (!material) return;
  const mats = Array.isArray(material) ? material : [material];
  for (const m of mats) {
    if (!m) continue;
    m.transparent = opacity < 1;
    m.opacity = opacity;
    m.needsUpdate = true;
  }
}

function setObjectOpacity(obj, opacity) {
  obj?.traverse?.(o => {
    if (o.material) setMaterialOpacity(o.material, opacity);
  });
}

function restoreObjectOpacity(obj) {
  obj?.traverse?.(o => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of mats) {
      if (!m) continue;
      const op = baseOpacity.has(m) ? baseOpacity.get(m) : 1;
      m.transparent = op < 1;
      m.opacity = op;
      m.needsUpdate = true;
    }
  });
}

function seededNoiseTexture() {
  let seed = 1234567;
  function rnd() {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const cnv = document.createElement('canvas');
  cnv.width = 96;
  cnv.height = 128;
  const ctx = cnv.getContext('2d');
  const img = ctx.createImageData(cnv.width, cnv.height);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 112 + rnd() * 118;
    img.data[i] = Math.min(255, v + rnd() * 45);
    img.data[i + 1] = Math.min(255, v + rnd() * 25);
    img.data[i + 2] = Math.min(255, v + rnd() * 55);
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  for (let k = 0; k < 16; k++) {
    ctx.fillStyle = `rgba(${70 + rnd() * 95},${70 + rnd() * 95},${70 + rnd() * 95},0.23)`;
    ctx.beginPath();
    ctx.ellipse(rnd() * cnv.width, rnd() * cnv.height, 7 + rnd() * 16, 5 + rnd() * 18, rnd() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(cnv);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function addEdges(mesh) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    lineMat(black, 1)
  );
  edges.renderOrder = 2;
  mesh.add(edges);
  return edges;
}

function createVolume({ id, x, y0 = 0, size, depth, noisy = false, attention = false, shade = 0 }) {
  const geom = new THREE.BoxGeometry(size, size, depth);
  const frontMat = noisy
    ? new THREE.MeshBasicMaterial({ map: seededNoiseTexture(), side: THREE.DoubleSide })
    : mat(new THREE.Color(copperLight).offsetHSL(0, -0.02, shade));
  if (!noisy) baseOpacity.set(frontMat, 1);
  const mats = noisy
    ? [
        mat(0x888888), mat(0x565656), mat(0xe0e0e0), mat(0x777777),
        frontMat, mat(0xa0a0a0)
      ]
    : [
        mat(0xa95432), mat(0x8a3d21), mat(0xd99370), mat(0x6e3119),
        frontMat, mat(copperDark)
      ];
  const mesh = new THREE.Mesh(geom, mats);
  mesh.position.set(x, y0 + size / 2, -depth / 2);
  mesh.userData = { id, size, depth, attention };
  addEdges(mesh);
  scene.add(mesh);
  architectureObjects.push(mesh);
  volumeMeshes.push(mesh);

  if (attention) {
    registerInteractive(mesh, {
      title: 'Self-attention block',
      tooltip: 'Click to inspect self-attention',
      body: 'At 16×16 resolution there are 256 spatial tokens. Self-attention computes A = softmax(QKᵀ / √d), so one selected position can mix information from every other position.',
      onClick: () => setAttentionOverlay(true)
    });
  }
  return mesh;
}

function arrow(points, color = black, opts = {}) {
  const group = new THREE.Group();
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), lineMat(color, opts.opacity ?? 1));
  group.add(line);

  if (opts.head !== false && points.length >= 2) {
    const a = points[points.length - 2];
    const b = points[points.length - 1];
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const headLen = opts.headLength ?? 0.16;
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(opts.headRadius ?? 0.055, headLen, 20),
      mat(color, opts.opacity ?? 1)
    );
    cone.position.copy(b).sub(dir.clone().multiplyScalar(headLen * 0.45));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    group.add(cone);
  }

  scene.add(group);
  architectureObjects.push(group);
  if (opts.pulsable) pulseObjects.push(group);
  return group;
}

function meshTop(mesh) {
  return new THREE.Vector3(mesh.position.x, mesh.position.y + mesh.userData.size / 2, 0.06);
}
function meshLow(mesh, side = 0) {
  return new THREE.Vector3(mesh.position.x + side * mesh.userData.size * 0.38, 0.08, 0.08);
}
function leftEdge(mesh) {
  return mesh.position.x - mesh.userData.size / 2;
}
function rightEdge(mesh) {
  return mesh.position.x + mesh.userData.size / 2;
}

const face = { s256: 2.9, s128: 1.55, s64: 0.85, s32: 0.55, s16: 0.34, s8: 0.24 };
const ch = { c3: 0.04, c128: 0.38, c256: 0.62, c512: 1.05 };

const stages = [
  { id: 'input', label: 'input image', mesh: createVolume({ id: 'input', x: -9.20, size: face.s256, depth: ch.c3, noisy: true }) },
  { id: 'enc256a', label: '256 encoder', mesh: createVolume({ id: 'enc256a', x: -8.05, size: face.s256, depth: ch.c128, shade: 0.01 }) },
  { id: 'enc256b', label: '256 encoder', mesh: createVolume({ id: 'enc256b', x: -7.25, size: face.s256, depth: ch.c128, shade: -0.04 }) },
  { id: 'enc128', label: '128 downsample', mesh: createVolume({ id: 'enc128', x: -5.65, size: face.s128, depth: ch.c128, shade: -0.02 }) },
  { id: 'enc64', label: '64 downsample', mesh: createVolume({ id: 'enc64', x: -4.45, size: face.s64, depth: ch.c256, shade: 0.01 }) },
  { id: 'enc32', label: '32 downsample', mesh: createVolume({ id: 'enc32', x: -3.35, size: face.s32, depth: ch.c256, shade: 0.02 }) },
  { id: 'enc16', label: '16 self-attention', mesh: createVolume({ id: 'enc16', x: -2.05, size: face.s16, depth: ch.c512, shade: 0.00, attention: true }) },
  { id: 'bottleneck', label: '8 bottleneck', mesh: createVolume({ id: 'bottleneck', x: -0.72, size: face.s8, depth: ch.c512, shade: -0.03, attention: true }) },
  { id: 'bottleneck2', label: '8 transition', mesh: createVolume({ id: 'bottleneck2', x: 0.62, size: face.s8, depth: ch.c512, shade: -0.02, attention: true }) },
  { id: 'dec16', label: 'decoder 16', mesh: createVolume({ id: 'dec16', x: 1.88, size: face.s16, depth: ch.c512, shade: 0.00, attention: true }) },
  { id: 'dec32', label: 'decoder 32', mesh: createVolume({ id: 'dec32', x: 3.10, size: face.s32, depth: ch.c256, shade: 0.02 }) },
  { id: 'dec64', label: 'decoder 64', mesh: createVolume({ id: 'dec64', x: 4.20, size: face.s64, depth: ch.c256, shade: 0.01 }) },
  { id: 'dec128', label: 'decoder 128', mesh: createVolume({ id: 'dec128', x: 5.45, size: face.s128, depth: ch.c128, shade: -0.02 }) },
  { id: 'dec256a', label: 'decoder 256', mesh: createVolume({ id: 'dec256a', x: 7.05, size: face.s256, depth: ch.c128, shade: -0.01 }) },
  { id: 'dec256b', label: 'decoder 256', mesh: createVolume({ id: 'dec256b', x: 7.86, size: face.s256, depth: ch.c128, shade: -0.05 }) },
  { id: 'output', label: 'output image', mesh: createVolume({ id: 'output', x: 9.10, size: face.s256, depth: ch.c3, noisy: true }) }
];

for (let i = 0; i < stages.length - 1; i++) {
  const a = stages[i].mesh;
  const b = stages[i + 1].mesh;
  const x1 = Math.min(rightEdge(a) + 0.05, (a.position.x + b.position.x) * 0.5 - 0.10);
  const x2 = Math.max(leftEdge(b) - 0.05, (a.position.x + b.position.x) * 0.5 + 0.10);
  const obj = arrow([
    new THREE.Vector3(x1, 0.05, 0.12),
    new THREE.Vector3(x2, 0.05, 0.12)
  ], black, { opacity: 0.88, headRadius: 0.04, headLength: 0.13, pulsable: true });
  transitionByStage[stages[i + 1].id] = obj;
}

const skipSpecs = [
  { from: 'enc256b', to: 'dec256a', y: 4.05, labelX: 0.75, stage: 'dec256a' },
  { from: 'enc128', to: 'dec128', y: 3.05, labelX: 0.15, stage: 'dec128' },
  { from: 'enc64', to: 'dec64', y: 2.16, labelX: -0.10, stage: 'dec64' },
  { from: 'enc32', to: 'dec32', y: 1.55, labelX: 0.00, stage: 'dec32' }
];

for (const s of skipSpecs) {
  const fromMesh = stages.find(st => st.id === s.from).mesh;
  const toMesh = stages.find(st => st.id === s.to).mesh;
  const start = meshTop(fromMesh);
  start.x = rightEdge(fromMesh) - 0.05;
  const end = meshTop(toMesh);
  end.x = leftEdge(toMesh) + 0.05;
  const pts = [
    start,
    new THREE.Vector3(start.x + 0.95, s.y, 0.13),
    new THREE.Vector3(end.x - 0.95, s.y, 0.13),
    end
  ];
  const obj = arrow(pts, copper, { opacity: 0.98, headRadius: 0.075, headLength: 0.22, pulsable: true });
  skipByStage[s.stage] = obj;
}

const timeY = -0.70;
const timeStartX = -9.95;
const timeEndX = 7.25;
arrow([new THREE.Vector3(timeStartX, timeY, 0.12), new THREE.Vector3(timeEndX, timeY, 0.12)], blue, { head: false, opacity: 0.98 });

const circlePts = [];
for (let i = 0; i <= 80; i++) {
  const a = i / 80 * Math.PI * 2;
  circlePts.push(new THREE.Vector3(timeStartX - 0.34 + Math.cos(a) * 0.28, timeY + Math.sin(a) * 0.28, 0.14));
}
const tCircle = new THREE.Line(new THREE.BufferGeometry().setFromPoints(circlePts), lineMat(blue, 1));
scene.add(tCircle);
architectureObjects.push(tCircle);

const injectionTargets = stages.filter(s => !['input', 'output'].includes(s.id));
for (const st of injectionTargets) {
  const baseX = Math.min(st.mesh.position.x - 0.70, timeEndX - 0.10);
  const dest = new THREE.Vector3(st.mesh.position.x - st.mesh.userData.size * 0.34, 0.15, 0.16);
  const obj = arrow([new THREE.Vector3(baseX, timeY, 0.12), dest], blue, {
    opacity: 0.92,
    headRadius: 0.048,
    headLength: 0.14,
    pulsable: true
  });
  injectionLines.push(obj);

  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 10), mat(blue, 0.86));
  dot.position.set(dest.x - 0.03, dest.y + 0.08, 0.20);
  scene.add(dot);
  architectureObjects.push(dot);
  injectionDots.push(dot);
}

function roundedRectShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const shape = new THREE.Shape();
  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + h - r);
  shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  shape.lineTo(x + r, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - r);
  shape.lineTo(x, y + r);
  shape.quadraticCurveTo(x, y, x + r, y);
  return shape;
}

const legendGroup = new THREE.Group();
legendGroup.position.set(-9.95, 3.82, 0.25);
const legendShape = roundedRectShape(2.28, 1.42, 0.20);
const legendPanel = new THREE.Mesh(new THREE.ShapeGeometry(legendShape), mat(0xffffff, 0.96));
legendGroup.add(legendPanel);
const legendOutline = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(legendShape.getPoints(64).map(p => new THREE.Vector3(p.x, p.y, 0.02))),
  lineMat(black, 1)
);
legendGroup.add(legendOutline);
function legendLine(y, col) {
  const pts = [new THREE.Vector3(-0.18, y, 0.04), new THREE.Vector3(0.38, y, 0.04)];
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat(col, 1));
  legendGroup.add(l);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.15, 18), mat(col, 1));
  cone.position.set(0.34, y, 0.04);
  cone.rotation.z = -Math.PI / 2;
  legendGroup.add(cone);
}
legendLine(0.43, 0x333b40);
legendLine(-0.10, 0xb7c9d7);
scene.add(legendGroup);
architectureObjects.push(legendGroup);

const halo = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1)),
  lineMat(0xffd34d, 0)
);
halo.material.depthTest = false;
scene.add(halo);

const overlayGroup = new THREE.Group();
overlayGroup.visible = false;
scene.add(overlayGroup);

const overlayPanel = new THREE.Mesh(new THREE.PlaneGeometry(5.8, 2.55), mat(0xffffff, 0.94));
overlayPanel.position.set(0, 2.58, 0.34);
overlayGroup.add(overlayPanel);
const overlayBorder = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.PlaneGeometry(5.8, 2.55)),
  lineMat(0x222222, 1)
);
overlayBorder.position.copy(overlayPanel.position);
overlayGroup.add(overlayBorder);

function grid(group, originX, originY, n, size, color, opacity = 0.45) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const k = i * size / n;
    pts.push(new THREE.Vector3(originX + k, originY, 0.39), new THREE.Vector3(originX + k, originY + size, 0.39));
    pts.push(new THREE.Vector3(originX, originY + k, 0.39), new THREE.Vector3(originX + size, originY + k, 0.39));
  }
  group.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts), lineMat(color, opacity)));
