      e.div.style.display = 'none';
      continue;
    }
    v.copy(e.pos).project(camera);
    if (v.z > 1 || v.z < -1 || v.x < -1 || v.x > 1 || v.y < -1 || v.y > 1) {
      e.div.style.display = 'none';
      continue;
    }
    e.div.style.display = '';
    const x = (v.x * 0.5 + 0.5) * canvas.clientWidth + (e.offset[0] || 0);
    const y = (-v.y * 0.5 + 0.5) * canvas.clientHeight + (e.offset[1] || 0);
    e.div.style.left = `${x}px`;
    e.div.style.top = `${y}px`;
