  div.style.cursor = opts.pointer ? 'pointer' : 'default';
  document.getElementById('stage').appendChild(div);
  const entry = {
    div,
    pos: position.clone(),
    angle: opts.angle ?? -34,
    offset: opts.offset || [0, 0],
    hidden: false
  };
  rotatedLabels.push(entry);
  return entry;
}

function syncRotatedLabels() {
  requestAnimationFrame(syncRotatedLabels);
  const v = new THREE.Vector3();
  for (const e of rotatedLabels) {
    if (e.hidden) {
      e.div.style.display = 'none';
      continue;
    }
    v.copy(e.pos).project(camera);
    if (v.z > 1 || v.z < -1 || v.x < -1 || v.x > 1 || v.y < -1 || v.y > 1) {
      e.div.style.display = 'none';
      continue;
    }
    e.div.style.display = '';
    const x = (v.x * 0.5 + 0.5) * canvas.clientWidth + (e.offset[0] || 0);
    const y = (-v.y * 0.5 + 0.5) * canvas.clientHeight + (e.offset[1] || 0);
    e.div.style.left = `${x}px`;
    e.div.style.top = `${y}px`;
    e.div.style.transform = `translate(-50%, -50%) rotate(${e.angle}deg)`;
  }
}
