  <button id="step2">Late t</button>
</div>
<div id="stepTitle" style="font-weight:bold;color:#7b3a24">Middle diffusion timestep</div>
<div id="stepNarration" style="line-height:1.35;color:#333">At an intermediate t, the blue time-embedding arrows carry a different conditioning value to all encoder and decoder blocks.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// legend box → rounded ShapeGeometry white panel with black outline in upper-left
// legend residual entry → dark horizontal Line arrow labeled "Res. block"
// legend self-attention entry → pale-blue horizontal Line arrow labeled "Res. block + self-attention"
// input image sheet → thin noisy BoxGeometry, H×W×C mapped to y×x×z-thickness as 256×256×3
// encoder feature volumes → orange/brown BoxGeometry cuboids with square x-y front faces and z channel depth
// decoder feature volumes → mirrored orange/brown BoxGeometry cuboids, same visible sizes for matching H×W×C
// volume outlines → black EdgesGeometry LineSegments on every cuboid
// dimension leaders → black Line arrows with cone heads from rotated HTML labels to corresponding volumes
// skip connections → copper polyline arrows above blocks, labeled "Concatenate", connecting equal-resolution encoder/decoder stages
// time node → muted-blue outlined circular Line labeled "t"
// time embedding line → muted-blue bottom Line labeled "time embedding"
// time injection arrows → muted-blue diagonal Line arrows from bottom line into each residual/self-attention block
// forward path arrowheads → small black Line arrows between successive feature volumes along baseline
// active stage halo → transparent yellow EdgesGeometry box around current stage during pass animation
// self-attention overlay → hidden Group with white panel, local residual mini-grid, 16×16 attention grid, query cell, and global attention rays

const copper = 0xcf7b5b;
const copperDark = 0x7f3a20;
const copperLight = 0xc97955;
const copperText = '#7b3a24';
const blue = 0x4b6d7c;
const paleBlueHex = 0x6f9bb5;
const paleBlueCss = '#6f9bb5';
const black = 0x000000;

const architectureObjects = [];
const pulseObjects = [];
const volumeMeshes = [];
const injectionLines = [];
const injectionDots = [];
const customLabels = [];
const skipByStage = {};
const transitionByStage = {};
const baseOpacity = new WeakMap();

let passRunning = false;
let passStart = 0;
let activeStageIndex = -1;
let attentionOpen = false;
const passStageMs = 820;

function mat(color, opacity = 1, extra = {}) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    ...extra
  });
  baseOpacity.set(m, opacity);
  return m;
}

function lineMat(color, opacity = 1) {
  const m = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  baseOpacity.set(m, opacity);
  return m;
}

function setMaterialOpacity(material, opacity) {
  const mats = Array.isArray(material) ? material : [material];
  for (const m of mats) {
    if (!m) continue;
    m.transparent = opacity < 1;
    m.opacity = opacity;
    m.needsUpdate = true;
  }
}

function setObjectOpacity(obj, opacity) {
  obj?.traverse?.(o => {
    if (o.material) setMaterialOpacity(o.material, opacity);
  });
}

function restoreObjectOpacity(obj) {
  obj?.traverse?.(o => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of mats) {
      const op = baseOpacity.has(m) ? baseOpacity.get(m) : 1;
      m.transparent = op < 1;
      m.opacity = op;
      m.needsUpdate = true;
    }
  });
}

function seededNoiseTexture() {
  let seed = 42217;
  function rnd() {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const cnv = document.createElement('canvas');
  cnv.width = 96;
  cnv.height = 128;
  const ctx = cnv.getContext('2d');
  const img = ctx.createImageData(cnv.width, cnv.height);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 105 + rnd() * 130;
    img.data[i] = Math.min(255, v + rnd() * 38);
    img.data[i + 1] = Math.min(255, v + rnd() * 22);
    img.data[i + 2] = Math.min(255, v + rnd() * 48);
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  for (let k = 0; k < 18; k++) {
    ctx.fillStyle = `rgba(${55 + rnd() * 95},${55 + rnd() * 95},${55 + rnd() * 95},0.22)`;
    ctx.beginPath();
    ctx.ellipse(rnd() * cnv.width, rnd() * cnv.height, 5 + rnd() * 15, 6 + rnd() * 20, rnd() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(cnv);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function addEdges(mesh) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    lineMat(black, 1)
  );
  edges.renderOrder = 4;
  mesh.add(edges);
  return edges;
}

function createVolume({ id, x, size, depth, noisy = false, attention = false, shade = 0 }) {
  const geom = new THREE.BoxGeometry(size, size, depth);
  const lit = new THREE.Color(copperLight).offsetHSL(0, -0.015, shade);
  const frontMat = noisy
    ? new THREE.MeshBasicMaterial({ map: seededNoiseTexture(), side: THREE.DoubleSide })
    : mat(lit);
  if (noisy) baseOpacity.set(frontMat, 1);

  const mats = noisy
    ? [
        mat(0x777777), mat(0x595959), mat(0xd7d7d7), mat(0x777777),
        frontMat, mat(0xa6a6a6)
      ]
    : [
        mat(0xa95432), mat(0x743217), mat(0xd28a68), mat(0x6d2f18),
        frontMat, mat(copperDark)
      ];

  const mesh = new THREE.Mesh(geom, mats);
  mesh.position.set(x, size / 2, -depth / 2);
  mesh.userData = { id, size, depth, attention };
  addEdges(mesh);
  scene.add(mesh);
  architectureObjects.push(mesh);
  volumeMeshes.push(mesh);

  if (attention) {
    registerInteractive(mesh, {
      title: 'Self-attention block',
      tooltip: 'Click to inspect self-attention',
      body: 'At 16×16 resolution there are 256 spatial tokens. Self-attention computes A = softmax(QKᵀ / √d), so one selected position can mix information from all other positions.',
      onClick: () => setAttentionOverlay(true)
    });
  }
  return mesh;
}

function arrow(points, color = black, opts = {}) {
  const group = new THREE.Group();
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), lineMat(color, opts.opacity ?? 1));
  group.add(line);

  if (opts.head !== false && points.length >= 2) {
    const a = points[points.length - 2];
    const b = points[points.length - 1];
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(opts.headRadius ?? 0.045, opts.headLength ?? 0.14, 22),
      mat(color, opts.opacity ?? 1)
    );
    cone.position.copy(b).sub(dir.clone().multiplyScalar((opts.headLength ?? 0.14) * 0.45));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    group.add(cone);
  }

  scene.add(group);
  architectureObjects.push(group);
  if (opts.pulsable) pulseObjects.push(group);
  return group;
}

function leftEdge(mesh) { return mesh.position.x - mesh.userData.size / 2; }
function rightEdge(mesh) { return mesh.position.x + mesh.userData.size / 2; }
function topFront(mesh, side = 0) {
  return new THREE.Vector3(mesh.position.x + side * mesh.userData.size * 0.42, mesh.userData.size + 0.02, 0.08);
