function customLabel(html, position, opts = {}) {
  const div = document.createElement('div');
  div.className = 'lbl';
  div.innerHTML = html;
  div.style.fontFamily = opts.family || 'serif';
  div.style.fontSize = opts.fontSize || '15px';
  div.style.color = opts.color || '#111';
  div.style.fontStyle = opts.italic ? 'italic' : 'normal';
  div.style.fontWeight = opts.bold ? 'bold' : 'normal';
  if (opts.background) {
    div.style.background = opts.background;
    div.style.padding = '1px 4px';
    div.style.borderRadius = '3px';
  }
  if (opts.pointer) {
    div.style.pointerEvents = 'auto';
    div.style.cursor = 'pointer';
  }
  document.getElementById('stage').appendChild(div);
  const entry = {
    div,
    pos: position.clone(),
    angle: opts.angle || 0,
    offset: opts.offset || [0, 0],
    hidden: !!opts.hidden
  };
  customLabels.push(entry);
  return entry;
}

function syncCustomLabels() {
  requestAnimationFrame(syncCustomLabels);
  const v = new THREE.Vector3();
  for (const e of customLabels) {
    if (e.hidden) {
      e.div.style.display = 'none';
      continue;
    }
    v.copy(e.pos).project(camera);
    if (v.z > 1 || v.z < -1 || v.x < -1 || v.x > 1 || v.y < -1 || v.y > 1) {
      e.div.style.display = 'none';
      continue;
    }
    e.div.style.display = '';
    const x = (v.x * 0.5 + 0.5) * canvas.clientWidth + (e.offset[0] || 0);
    const y = (-v.y * 0.5 + 0.5) * canvas.clientHeight + (e.offset[1] || 0);
    e.div.style.left = `${x}px`;
    e.div.style.top = `${y}px`;
    e.div.style.transform = `translate(-50%, -50%) rotate(${e.angle}deg)`;
  }
}
