function setActiveStage(idx) {
  activeStageIndex = idx;
  const st = stages[idx];
  if (!st || attentionOpen) {
    setObjectOpacity(halo, 0);
    return;
  }
  const mesh = st.mesh;
  halo.position.copy(mesh.position);
  halo.scale.set(mesh.userData.size + 0.16, mesh.userData.size + 0.16, mesh.userData.depth + 0.16);
  setObjectOpacity(halo, 0.62);
}

function updateTimestep(value) {
  const t = Number(value);
  document.getElementById('tReadout').textContent = t;
  tValueLabel.div.innerHTML = `t = ${t}`;
  const s = Math.sin(2 * Math.PI * t / 1000);
  const c = Math.cos(2 * Math.PI * t / 1000);
  const g = Math.round(95 + 105 * (s * 0.5 + 0.5));
  const b = Math.round(125 + 92 * (c * 0.5 + 0.5));
  const color = new THREE.Color(`rgb(60,${g},${b})`);
  for (const obj of injectionLines) {
    obj.traverse(o => {
      if (o.material?.color) o.material.color.copy(color);
    });
  }
  for (const dot of injectionDots) {
    dot.material.color.copy(color);
    dot.scale.setScalar(0.82 + 0.50 * (s * 0.5 + 0.5));
  }
}

