function interactionTick() {
  requestAnimationFrame(interactionTick);
  const now = performance.now();
  const wave = 0.5 + 0.5 * Math.sin(now * 0.008);

  if (passRunning) {
    const idx = Math.min(stages.length - 1, Math.floor((now - passStart) / passStageMs));
    if (idx !== activeStageIndex) setActiveStage(idx);
    if (idx >= stages.length - 1 && now - passStart > passStageMs * stages.length) passRunning = false;
  }

  if (!attentionOpen && activeStageIndex >= 0) {
    setObjectOpacity(halo, 0.28 + 0.42 * wave);
  }

  for (const obj of pulseObjects) restoreObjectOpacity(obj);

  const activeId = stages[activeStageIndex]?.id;
  const activeTransition = transitionByStage[activeId];
  const activeSkip = skipByStage[activeId];
  if (activeTransition && !attentionOpen) setObjectOpacity(activeTransition, 0.55 + 0.45 * wave);
  if (activeSkip && !attentionOpen) setObjectOpacity(activeSkip, 0.42 + 0.58 * wave);
}
